// @generated by the slice schematic from its spec. Edit in place; reshape via the spec and --force.
import { z } from 'zod';
import type { FormFieldMeta } from '../forms/form-field-meta';

export const heroSchema = z.object({
  name: z
    .string()
    .min(1, 'Hero name is required')
    .meta({
      label: 'Hero name',
      control: 'text',
      placeholder: 'e.g. Silverwing',
    } satisfies FormFieldMeta),
  alias: z.string().meta({
    label: 'Civilian alias',
    control: 'text',
    placeholder: 'Secret identity, or Unknown',
  } satisfies FormFieldMeta),
  powerClass: z.enum(['Aerial', 'Energy', 'Psionic', 'Tech', 'Mutant', 'Cosmic', 'Enhanced']).meta({
    label: 'Power class',
    control: 'select',
    options: [
      { value: 'Aerial', label: 'Aerial' },
      { value: 'Energy', label: 'Energy' },
      { value: 'Psionic', label: 'Psionic' },
      { value: 'Tech', label: 'Tech' },
      { value: 'Mutant', label: 'Mutant' },
      { value: 'Cosmic', label: 'Cosmic' },
      { value: 'Enhanced', label: 'Enhanced' },
    ],
  } satisfies FormFieldMeta),
  power: z
    .number()
    .min(0, 'Power index must be at least 0')
    .max(100, 'Power index must not exceed 100')
    .meta({
      label: 'Power index',
      control: 'number',
      help: 'Scale of 0 to 100.',
    } satisfies FormFieldMeta),
  notes: z.string().meta({
    label: 'Dossier notes',
    control: 'textarea',
    help: 'Capabilities and deployment guidance.',
  } satisfies FormFieldMeta),
  active: z.boolean().meta({
    label: 'On active roster',
    control: 'checkbox',
    help: 'Off keeps the hero on file but out of deployments.',
  } satisfies FormFieldMeta),
});

export type HeroFormModel = z.infer<typeof heroSchema>;
